import java.util.List;
import java.util.Scanner;

interface Payable {
    int amount();                       // every Payable must say how much it is

    default String receipt() {          // shared by all implementations
        return "Paid: " + amount();
    }
}

class Invoice implements Payable {
    private final int total;

    Invoice(int total) {
        this.total = total;
    }

    public int amount() {
        return 0; // TODO: an invoice is worth its total
    }
}

class Salary implements Payable {
    private final int base;
    private final int bonus;

    Salary(int base, int bonus) {
        this.base = base;
        this.bonus = bonus;
    }

    public int amount() {
        return 0; // TODO: a salary is the base plus the bonus
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        List<Payable> items = new ArrayList<>();
