import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

interface Payable {
    int amount();

    default String receipt() {
        return "Paid: " + amount();
    }
}

class Invoice implements Payable {
    private final int total;

    Invoice(int total) {
        this.total = total;
    }

    public int amount() {
        return total;
    }
}

class Salary implements Payable {
    private final int base;
    private final int bonus;

    Salary(int base, int bonus) {
        this.base = base;
        this.bonus = bonus;
    }

    public int amount() {
        return base + bonus;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        List<Payable> items = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (sc.next().equals("I")) items.add(new Invoice(sc.nextInt()));
            else items.add(new Salary(sc.nextInt(), sc.nextInt()));
        }
        int total = 0;
        for (Payable p : items) {
            System.out.println(p.receipt());
            total += p.amount();
        }
        System.out.println("Total: " + total);
    }
}
